function buildCategory(cat: IELTSStrategyCategory, prefix: string, seeds: StrategySeedTuple[]): IELTSStrategyLesson[] {
  return seeds.map((s, idx) => {
    const id = `ielts-strat-${prefix}-${String(idx + 1).padStart(2, '0')}`;
    const [
      title, cefrTarget, skillFocus, corePrinciple, steps,
      trapName, howItTricks, counterMove, timingNote, snippet, breakdown,
      q1Prompt, q1Options, q1Ans, q1Exp, q1ExpVi,
    ] = s;
    const trapDistractor = howItTricks.replace(/\.$/, '');
    return {
      id,
      category: cat,
      title,
      cefrTarget,
      skillFocus,
      corePrinciple,
      stepByStepMethod: steps,
      trapPatterns: [{ trapName, howItTricks, counterMove }],
      timingAllocationNote: timingNote,
      exampleBox: { snippet, breakdown },
      exercises: [
        iEx({
          id: `${id}-ex-1`,
          lessonId: id,
          type: 'multiple_choice',
          instruction: 'Select the accurate IELTS tactical principle.',
          prompt: `[Strategy • ${title}] ${q1Prompt}`,
          options: q1Options,
          correctAnswer: q1Ans,
          explanation: q1Exp,
          explanationVi: q1ExpVi,
          difficulty: cefrTarget === 'C1' ? 3 : 2,
          skills: [cat === 'exam_day' ? 'reading' : cat],
        }),
        iEx({
          id: `${id}-ex-2`,
          lessonId: id,
          type: 'multiple_choice',
          instruction: 'Select the tactical counter-move neutralizing the named trap.',
          prompt: `[Trap Counter • ${title} (${skillFocus})] When facing "${trapName}", which action defeats it cleanly?`,
          options: [
            counterMove,
            `Let this habit continue unchecked: ${trapDistractor}.`,
            'Stop moving through subsequent items silently for 30 seconds.',
            'Switch randomly without checking timing bounds or context cues.',
          ],
          correctAnswer: counterMove,
          explanation: `Trap warning: ${howItTricks} Effective counter: ${counterMove}`,
          explanationVi: `Cách khắc chế bẫy "${trapName}": ${counterMove}`,
          difficulty: cefrTarget === 'C1' ? 3 : 2,
          skills: [cat === 'exam_day' ? 'reading' : cat],
        }),
      ],
    };
  });
}

export const IELTS_STRATEGY_LESSONS: IELTSStrategyLesson[] = [
  ...buildCategory('listening', 'lis', LISTENING_SEEDS),
  ...buildCategory('reading', 'rd', READING_SEEDS),
  ...buildCategory('writing', 'wrt', WRITING_SEEDS),
  ...buildCategory('speaking', 'spk', SPEAKING_SEEDS),
  ...buildCategory('exam_day', 'day', EXAM_DAY_SEEDS),
];
